        /// Removes <see cref="InputAction.started"/>, <see cref="InputAction.performed"/> and <see cref="InputAction.canceled"/> callbacks provided via <param cref="instance" /> on all input actions contained in this map.
        /// </summary>
        /// <remarks>
        /// Calling this method when <paramref name="instance" /> have not previously been registered has no side-effects.
        /// </remarks>
        /// <seealso cref="RamboActions" />
        private void UnregisterCallbacks(IRamboActions instance)
        {
            @LetterR.started -= instance.OnLetterR;
            @LetterR.performed -= instance.OnLetterR;
            @LetterR.canceled -= instance.OnLetterR;
            @LetterA.started -= instance.OnLetterA;
            @LetterA.performed -= instance.OnLetterA;
            @LetterA.canceled -= instance.OnLetterA;
            @LetterM.started -= instance.OnLetterM;
            @LetterM.performed -= instance.OnLetterM;
            @LetterM.canceled -= instance.OnLetterM;
            @LetterB.started -= instance.OnLetterB;
            @LetterB.performed -= instance.OnLetterB;
            @LetterB.canceled -= instance.OnLetterB;
            @LetterO.started -= instance.OnLetterO;
            @LetterO.performed -= instance.OnLetterO;
            @LetterO.canceled -= instance.OnLetterO;
        }

        /// <summary>
        /// Unregisters <param cref="instance" /> and unregisters all input action callbacks via <see cref="RamboActions.UnregisterCallbacks(IRamboActions)" />.
        /// </summary>
        /// <seealso cref="RamboActions.UnregisterCallbacks(IRamboActions)" />
        public void RemoveCallbacks(IRamboActions instance)
        {
            if (m_Wrapper.m_RamboActionsCallbackInterfaces.Remove(instance))
                UnregisterCallbacks(instance);
        }

        /// <summary>
        /// Replaces all existing callback instances and previously registered input action callbacks associated with them with callbacks provided via <param cref="instance" />.
        /// </summary>
        /// <remarks>
        /// If <paramref name="instance" /> is <c>null</c>, calling this method will only unregister all existing callbacks but not register any new callbacks.
        /// </remarks>
        /// <seealso cref="RamboActions.AddCallbacks(IRamboActions)" />
        /// <seealso cref="RamboActions.RemoveCallbacks(IRamboActions)" />
        /// <seealso cref="RamboActions.UnregisterCallbacks(IRamboActions)" />
        public void SetCallbacks(IRamboActions instance)
        {
            foreach (var item in m_Wrapper.m_RamboActionsCallbackInterfaces)
                UnregisterCallbacks(item);
            m_Wrapper.m_RamboActionsCallbackInterfaces.Clear();
            AddCallbacks(instance);
        }
    }
